const partnerId = $('Préparer Données Appel').first().json.partner_id || 101;
const oppId = $('Créer Opportunité CRM').first().json.result || false;
const prepData = $('Préparer Données Appel').first().json;
const items = Array.isArray(prepData.items) ? prepData.items : [];

const catalogMap = {
  "switch cisco 24": { id: 181, price: 4500.0 },
  "switch cisco": { id: 181, price: 4500.0 },
  "switch poe": { id: 113, price: 2200.0 },
  "borne wifi": { id: 114, price: 1600.0 },
  "unifi": { id: 114, price: 1600.0 },
  "routeur mikrotik": { id: 112, price: 900.0 },
  "mikrotik": { id: 112, price: 900.0 },
  "routeur cisco": { id: 180, price: 8500.0 },
  "jabra": { id: 119, price: 1800.0 },
  "casque": { id: 119, price: 1800.0 },
  "onduleur": { id: 120, price: 4800.0 },
  "serveur": { id: 115, price: 25000.0 },
  "meraki": { id: 118, price: 8000.0 },
  "fortigate": { id: 182, price: 7500.0 },
  "dahua": { id: 171, price: 1400.0 },
  "hikvision 4mp": { id: 170, price: 1500.0 },
  "hikvision ptz": { id: 172, price: 6000.0 },
  "disque dur": { id: 178, price: 1200.0 },
  "4 to": { id: 178, price: 1200.0 },
  "nvr": { id: 173, price: 3000.0 },
  "grandstream": { id: 130, price: 1200.0 },
  "yealink": { id: 110, price: 1500.0 },
  "baie": { id: 116, price: 3500.0 }
};

function matchProduct(name) {
  const low = (name || '').toLowerCase();
  for (const [key, val] of Object.entries(catalogMap)) {
    if (low.includes(key)) return val;
  }
  return { id: 181, price: 4500.0 };
}

let orderLines = [];
if (items.length > 0) {
  orderLines = items.map(item => {
    const prodInfo = matchProduct(item.product_name);
    return [0, 0, {
      product_id: item.product_id || prodInfo.id,
      product_uom_qty: Number(item.quantity) || 1,
      price_unit: Number(item.unit_price) || prodInfo.price
    }];
  });
} else {
  orderLines = [[0, 0, {
    product_id: 181,
    product_uom_qty: 1,
    price_unit: 4500.0
  }]];
}

const payload = {
  jsonrpc: "2.0",
  method: "call",
  params: {
    service: "object",
    method: "execute_kw",
    args: [
      "it_mall_db",
      2,
      "admin",
      "sale.order",
      "create",
      [
        {
          partner_id: partnerId,
          opportunity_id: oppId,
          order_line: orderLines
        }
      ]
    ]
  },
  id: 2
};

return [{ json: { payload: payload } }];
